using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
namespace RoadGunner.ConceptArt.Editor {
 public static class ConceptTerrainSurface {
 static Vector2 W(float x,float z){var p=Quaternion.Euler(0,45,0)*new Vector3(x*2.5f,0,z*2.5f);return new Vector2(p.x,p.z);}
 static Vector2[][] routes={new[]{W(0,-55),W(0,-43),W(1.5f,-25),W(0,-5),W(0,22),W(-1,42),W(0,60)},new[]{W(0,22),W(-17,22),W(-30,24),W(-43,24)},new[]{W(0,22),W(15,22),W(35,23),W(39,33)},new[]{W(0,36.5f),W(16,36.5f),W(24,40)},new[]{W(0,-9),W(-11,-9),W(-22,-16)}};
 public static string Apply(LevelLayout l){const int n=1024;const float span=512;var tex=new Texture2D(n,n,TextureFormat.RGBA32,false);var pixels=new Color[n*n];var light=ArtKit.Color("F7C78B");var dark=ArtKit.Color("DB9E66");for(int y=0;y<n;y++)for(int x=0;x<n;x++){var p=new Vector2((x+.5f)/n*span-span*.5f,(y+.5f)/n*span-span*.5f);float broad=Mathf.PerlinNoise(p.x*.036f+48,p.y*.036f+92);float secondary=Mathf.PerlinNoise(p.x*.15f+82,p.y*.15f+15);float f=Mathf.Clamp01(.5f+(broad-.5f)*1.3f+(secondary-.5f)*.18f);Color c=Color.Lerp(dark,light,f);float dist=1000,along=0;for(int r=0;r<routes.Length;r++){float length=0;for(int j=1;j<routes[r].Length;j++){var a=routes[r][j-1];var delta=routes[r][j]-a;float t=Mathf.Clamp01(Vector2.Dot(p-a,delta)/delta.sqrMagnitude);float d=Vector2.Distance(p,a+delta*t);if(d<dist){dist=d;along=length+t*delta.magnitude;}length+=delta.magnitude;}}float worn=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(5.0f,9.3f,dist+(secondary-.5f)*1.6f));c=Color.Lerp(c,c*new Color(.985f,.979f,.963f),worn*.65f);float rut=Mathf.Exp(-Mathf.Pow((dist-1.15f)/.18f,2))*.26f;float tread=.55f+.45f*Mathf.SmoothStep(.2f,.8f,Mathf.Repeat(along*2.4f,1));c=Color.Lerp(c,c*new Color(.83f,.78f,.70f),rut*tread);c.a=1;pixels[y*n+x]=c;}tex.SetPixels(pixels);tex.Apply();string path=ArtKit.Root+"/Textures/World desert soft routes.png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=true;imp.mipmapEnabled=true;imp.wrapMode=TextureWrapMode.Clamp;imp.maxTextureSize=n;imp.textureCompression=TextureImporterCompression.CompressedHQ;imp.anisoLevel=2;imp.SaveAndReimport();string matPath=ArtKit.Root+"/Materials/Continuous desert surface.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!m){m=new Material(Shader.Find("RoadGunner/Concept Desert"));AssetDatabase.CreateAsset(m,matPath);}m.shader=Shader.Find("RoadGunner/Concept Desert");m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));m.SetFloat("_WorldScale",span);m.enableInstancing=true;EditorUtility.SetDirty(m);var ground=l.ground.GetComponent<Renderer>();ground.sharedMaterial=m;EditorUtility.SetDirty(ground);foreach(var r in l.decorationRoot.Find("00 · Routes and clear ground").GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>old&&(old.name=="Track"||old.name=="SandLight"||old.name==m.name)?m:old).ToArray();EditorUtility.SetDirty(r);}foreach(var r in l.authoredContentRoot.GetComponentsInChildren<Renderer>(true)){if(r is MeshRenderer&&r.bounds.size.y<.6f&&r.sharedMaterials.Length>0&&r.sharedMaterials.All(old=>old&&(old.name=="Track"||old.name=="Sand"||old.name=="SandLight"||old.name=="SandShade"||old.shader.name=="RoadGunner/Concept Desert"))){r.sharedMaterials=r.sharedMaterials.Select(old=>m).ToArray();EditorUtility.SetDirty(r);if(PrefabUtility.IsPartOfPrefabInstance(r))PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}return "Continuous world-mapped desert + softly worn routes and clearings; terrain and route geometry unchanged";}
 }
